def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    bg = max({v for row in a for v in row}, key=lambda c: sum(row.count(c) for row in a))
    seen = set()
    for y in range(h):
        for x in range(w):
            c = a[y][x]
            if c == bg or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            comp = []
            while stack:
                yy, xx = stack.pop()
                comp.append((yy, xx))
                for ny, nx in ((yy+1,xx),(yy-1,xx),(yy,xx+1),(yy,xx-1)):
                    if 0 <= ny < h and 0 <= nx < w and a[ny][nx] == c and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            top, bottom = min(yy for yy,xx in comp), max(yy for yy,xx in comp)
            left, right = min(xx for yy,xx in comp), max(xx for yy,xx in comp)
            if bottom-top < 2 or right-left < 2:
                continue
            border = set((yy,xx) for yy in range(top,bottom+1) for xx in range(left,right+1)
                         if yy in (top,bottom) or xx in (left,right))
            if border.issubset(set(comp)):
                fill = 2 if (bottom-top-1) % 2 == 0 and (right-left-1) % 2 == 0 else 7
                for yy in range(top+1,bottom):
                    for xx in range(left+1,right):
                        if a[yy][xx] == bg:
                            a[yy][xx] = fill
    return a
